import React from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import InfoOutlined from '@mui/icons-material/InfoOutlined';
import UploadFileIcon from '@mui/icons-material/UploadFile';
import { Link as RouterLink } from 'react-router-dom';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';

export type QuantificationSummary = {
  activitySharePct?: number;
  spendBasedSharePct?: number;
  tier1SharePct?: number;
  tier2SharePct?: number;
  tier3SharePct?: number;
  primaryBasis?: 'activity_based' | 'spend_based';
  uncertaintyNote?: string;
};

type QuantificationMethodBannerProps = {
  summary?: QuantificationSummary | null;
  compact?: boolean;
  showUploadCta?: boolean;
  /** Name activity share and spend-proxy share separately. Default keeps the existing split bar. */
  presentSharesSeparately?: boolean;
};

const QuantificationMethodBanner: React.FC<QuantificationMethodBannerProps> = ({
  summary,
  compact = false,
  showUploadCta = true,
  presentSharesSeparately = false,
}) => {
  if (!summary) {
    return null;
  }

  const spendPct = Number(summary.spendBasedSharePct) || 0;
  const tier1 = Number(summary.tier1SharePct) || 0;
  const tier2 = Number(summary.tier2SharePct) || 0;
  const tier3 = Number(summary.tier3SharePct) || 0;
  const activityShare = Number(summary.tier1SharePct);
  const spendProxyShare = Number(summary.spendBasedSharePct);
  const hasActivityShare = summary.tier1SharePct != null && Number.isFinite(activityShare);
  const hasSpendProxy = summary.spendBasedSharePct != null && Number.isFinite(spendProxyShare);
  const showSeparateShares = presentSharesSeparately && (hasActivityShare || hasSpendProxy);
  const showBothShares = showSeparateShares && hasActivityShare && hasSpendProxy;
  const isSpendHeavy = summary.primaryBasis === 'spend_based' || spendPct >= 50;

  return (
    <Alert
      severity={isSpendHeavy ? 'warning' : 'info'}
      icon={<InfoOutlined fontSize="small" />}
      sx={{ mb: compact ? 1 : 2 }}
    >
      <Stack spacing={1}>
        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
          <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
            How your carbon was calculated
          </Typography>
          <Chip
            size="small"
            label={
              showBothShares
                ? 'Separate metrics'
                : (isSpendHeavy ? 'Mostly from ₹ spend' : 'Mostly from bill units')
            }
            color={showBothShares ? 'info' : (isSpendHeavy ? 'warning' : 'success')}
          />
        </Stack>

        {!compact && (
          showSeparateShares ? (
            <Stack spacing={0.25}>
              {hasActivityShare ? (
                <Typography variant="caption" color="text.secondary">
                  Activity share from bill units: {activityShare}%
                </Typography>
              ) : null}
              {hasSpendProxy ? (
                <Typography variant="caption" color="text.secondary">
                  Spend-proxy share: {spendProxyShare}%
                </Typography>
              ) : null}
            </Stack>
          ) : (
            <Box>
              <Stack direction="row" justifyContent="space-between" sx={{ mb: 0.5 }}>
                <Typography variant="caption" color="text.secondary">
                  From bill units: {tier1}%
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  From ₹ spend / estimates: {Math.min(100, tier2 + tier3)}%
                </Typography>
              </Stack>
              <LinearProgress
                variant="determinate"
                value={Math.min(100, tier1)}
                sx={{ height: 6, borderRadius: 1, mb: 0.5 }}
                color="success"
              />
            </Box>
          )
        )}

        <Typography variant="body2">
          {summary.uncertaintyNote
            || (showBothShares
              ? `Activity share from bill units is ${activityShare}%. Spend-proxy share is ${spendProxyShare}%. These are different inputs, not parts of one total.`
              : (isSpendHeavy
                ? 'Most of your carbon is still estimated from ₹ spend. Upload power, fuel, or water bills so we can use real units.'
                : 'Good — most of your carbon uses real bill units. Keep uploading new bills as they arrive.'))}
        </Typography>

        {showUploadCta && isSpendHeavy ? (
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap alignItems="center">
            <Button
              size="small"
              variant="contained"
              component={RouterLink}
              to={DOCUMENT_UPLOAD_PATH}
              startIcon={<UploadFileIcon />}
            >
              Upload bills
            </Button>
            {tier1 < 35 ? (
              <Typography variant="caption" color="text.secondary">
                Tip: clearer bills with units improve your score faster.
              </Typography>
            ) : null}
          </Stack>
        ) : null}
      </Stack>
    </Alert>
  );
};

export default QuantificationMethodBanner;
