import React from 'react';
import { Box, Typography } from '@mui/material';

export type InventoryCheckRow = {
  check: string;
  transactions: number;
  includedTransactions: number;
  kgCo2e: number;
  shareOfIncludedKgPercent: number;
  meaning?: string;
};

const ALWAYS_SHOWN = new Set([
  'Vouchers in this download',
  'Activity-based',
  'Spend-based',
  'Estimate',
  'Supplier primary',
  'Data quality: Tier 1 — activity',
  'Data quality: Tier 2 — spend',
  'Data quality: Tier 3 — estimate',
  'Within tolerance',
  'Outside tolerance',
  'Missing worked calculation',
  'ISO lines equal the voucher total',
]);

const formatKg = (value: number) => {
  const number = Number(value);
  if (!Number.isFinite(number)) return '0';
  return number.toLocaleString(undefined, { maximumFractionDigits: 2 });
};

const formatShare = (value: number) => {
  const number = Number(value);
  if (!Number.isFinite(number)) return '0';
  return number.toLocaleString(undefined, { maximumFractionDigits: 1 });
};

type InventoryChecksPanelProps = {
  checks?: InventoryCheckRow[] | null;
};

const InventoryChecksPanel: React.FC<InventoryChecksPanelProps> = ({ checks }) => {
  const rows = (Array.isArray(checks) ? checks : []).filter((row) => (
    ALWAYS_SHOWN.has(row.check) || Number(row.transactions) > 0
  ));
  if (rows.length === 0) return null;

  return (
    <Box data-testid="inventory-checks-panel">
      <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
        Inventory checks
      </Typography>
      <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
        Same counts as the Inventory checks sheet in the transaction audit workbook: method, data-quality tier, tolerance, and share of included kilograms.
      </Typography>
      <Box
        component="table"
        sx={{
          width: '100%',
          borderCollapse: 'collapse',
          '& th, & td': {
            textAlign: 'left',
            borderBottom: '1px solid',
            borderColor: 'divider',
            py: 0.75,
            pr: 1.5,
            verticalAlign: 'top',
            fontSize: '0.8125rem',
          },
          '& th:not(:first-of-type), & td:not(:first-of-type)': {
            textAlign: 'right',
            whiteSpace: 'nowrap',
          },
          '& th': { color: 'text.secondary', fontWeight: 600 },
        }}
      >
        <thead>
          <tr>
            <th>Check</th>
            <th>Transactions</th>
            <th>In inventory</th>
            <th>kg CO₂e</th>
            <th>Share</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.check}>
              <td>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>{row.check}</Typography>
                {row.meaning ? (
                  <Typography variant="caption" color="text.secondary" display="block">
                    {row.meaning}
                  </Typography>
                ) : null}
              </td>
              <td>{row.transactions}</td>
              <td>{row.includedTransactions}</td>
              <td>{formatKg(row.kgCo2e)}</td>
              <td>{formatShare(row.shareOfIncludedKgPercent)}%</td>
            </tr>
          ))}
        </tbody>
      </Box>
    </Box>
  );
};

export default InventoryChecksPanel;
